import path from "node:path";
import { openDemoDb } from "./db";
import { deleteCommit, getCommitForVerification, upsertCommits } from "./commits";
import { upsertIssues } from "./issues";
import { getMetrics, getRoster } from "./metrics";
import { listRuns, recordRun } from "./runs";
import type { Store } from "../types";

/** The one demo dataset. Regenerated by `npm run seed-demo -- --target sqlite`. */
export const DEMO_DB_PATH = path.join(process.cwd(), "data", "demo.sqlite");

export function sqliteStore(filePath: string = DEMO_DB_PATH): Store {
  const db = openDemoDb(filePath);

  return {
    upsertCommits: async (rows) => upsertCommits(db, rows),
    getCommitForVerification: async (sha) => getCommitForVerification(db, sha),
    deleteCommit: async (sha) => deleteCommit(db, sha),
    upsertIssues: async (rows) => upsertIssues(db, rows),
    recordRun: async (summary) => recordRun(db, summary),
    listRuns: async (limit) => listRuns(db, limit),
    getMetrics: async (query) => getMetrics(db, query),
    getRoster: async (displayNames) => getRoster(db, displayNames),
  };
}
